 ICON.aeKeys=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${AE_box(20,30,80,80,{fill:INK,st:INK,r:18})}${AE_C(60,70,14,{fill:'#FFFFFF',st:'#FFFFFF',sw:1})}${[0,1,2].map(i=>AE_arc(116,70,20+i*18,-40,40,GRN,5)).join('')}${AE_box(220,30,180,80,{fill:'#E3F4E6',st:GRN,sw:3,r:12})}${AE_T(310,82,'doors',{fs:28,fw:800,a:'middle',fill:GRN})}${AE_C(60,240,30,{fill:'#FFFFFF',st:INK,sw:5})}<rect x="46" y="226" width="28" height="28" fill="${PUR}"/>${AE_L(90,240,150,240,INK,10)}${AE_C(176,240,22,{fill:'none',st:PUR,sw:4})}${AE_C(176,240,34,{fill:'none',st:PUR,sw:3,ex:'stroke-dasharray="6 6"'})}${AE_box(220,200,180,80,{fill:'#F1ECFF',st:PUR,sw:3,r:12})}${AE_T(310,252,'start',{fs:28,fw:800,a:'middle',fill:PUR})}</g>`;
